if (N % 2 != 0) {
        throw std::invalid_argument("N must be even for Simpson's rule.");
    }

    double h = (b - a) / N;
    double sum = f(a) + f(b); // Start with the first and last points

    for (int i = 1; i < N; ++i) {
        double x = a + i * h;
        if (i % 2 == 0) {
            sum += 2 * f(x); // For even indices, coefficient is 2
        } else {
            sum += 4 * f(x); // For odd indices, coefficient is 4
        }
    }

    return (h / 3) * sum;

